window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[336]={"id":"336","numero":336,"titre":"Coma non traumatique","objectifs":[{"id":"336-1","rang":"A","rubrique":"Définition","titre":"Coma chez l’adulte et chez l’enfant","contenu":"<p>La <span class=\"kw-def\"><strong>conscience</strong></span> se divise schématiquement en deux composantes :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Éveil</span></strong> (ou vigilance, <em>wakefulness</em>) — sous le contrôle de neurones du <span class=\"kw-def\">tronc cérébral</span> (substance réticulée activatrice ascendante), de la partie postérieure du pont et du mésencéphale, et du diencéphale. Régule le niveau de vigilance (éveil, sommeil lent, sommeil paradoxal).</li>\n        <li><strong><span class=\"kw-def\">Contenu conscient</span></strong> (conscience de soi et de l'environnement, <em>awareness</em>) — sous-tendu par un réseau de neurones à connexion longue distance, situés surtout dans <span class=\"kw-clinique\">les</span> régions associatives <span class=\"kw-def\">préfrontales et pariétales</span>.</li>\n      </ul>\n      <p>Le <span class=\"kw-def\"><strong>coma</strong></span> est défini par une <strong>suppression de la vigilance</strong> (l'éveil, composante de la conscience). Il <span class=\"kw-clinique\">ne peut pas être reversé par un stimulus auditif ou douloureux</span>, <span class=\"kw-alerte\">sauf en cas de coma dépassé</span>. Il peut apparaître d'emblée ou faire suite à une <span class=\"kw-clinique\">obnubilation</span> puis à une <span class=\"kw-clinique\">stupeur</span>.</p>\n      <table >\n        <thead><tr><th>Degré d'altération</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Obnubilation</strong></span></td><td>persistance d'une <span class=\"kw-clinique\">réaction aux ordres complexes</span> : le patient répond à un ordre oral et écrit, exécute <span class=\"kw-clinique\">les</span> ordres, l'orientation temporo-spatiale est normale ; la réactivité est moins rapide et moins précise</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>État stuporeux</strong></span></td><td>persistance d'une <span class=\"kw-clinique\">réactivité à des stimuli extéroceptifs simples</span> (appel du nom, stimulation auditive, stimulation nociceptive) ; la réponse obtenue est un geste ou une parole</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Coma</strong></span></td><td>suppression de la vigilance ; le patient a <span class=\"kw-clinique\">les</span> yeux spontanément fermés, paraît inconscient et ne répond pas de façon adaptée malgré la stimulation auditive puis nociceptive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Diagnostics différentiels (rang C — pour mémoire).</strong>\n        <ul>\n          <li><strong><span class=\"kw-clinique\">Aphasie</span> globale / état psychotique</strong> : ne parle pas, n'obéit pas, mais bouge et garde <span class=\"kw-clinique\">les</span> yeux ouverts</li>\n          <li><strong>Mutisme akinétique</strong> : <span class=\"kw-clinique\">syndrome frontal</span> bilatéral, yeux ouverts mais ne bouge pas, absence de <span class=\"kw-clinique\">déficit moteur</span>, réflexes et tonus normaux</li>\n          <li><strong>Locked-in syndrome</strong> (désafférentation motrice) : <span class=\"kw-clinique\">infarctus</span> protubérantiel bilatéral — quadriplégie, diplégie faciale, paralysie de la latéralité du regard, <span class=\"kw-clinique\">conservation des mouvements de verticalité</span> ; vigilance et conscience normales</li>\n          <li><strong>Simulation / hystérie</strong> : yeux fermés, opposition active à la levée des paupières, évitement de la main lâchée vers le visage</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"336-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes pouvant concourir au coma","contenu":"<p>Le <span class=\"kw-clinique\">coma</span> traduit une <strong><span class=\"kw-alerte\">défaillance</span> de la <span class=\"kw-def\">formation réticulée activatrice ascendante</span> (FRAA)</strong> du tronc cérébral.</p>\n      <table >\n        <thead><tr><th>FRAA</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Localisation</strong></td><td>partie postérieure du <span class=\"kw-def\">pont</span> et du <span class=\"kw-def\">mésencéphale</span> ; partie postéro-antérieure du <span class=\"kw-def\">diencéphale</span></td></tr>\n          <tr><td><strong>Rôle</strong></td><td>support neurophysiologique de la <span class=\"kw-def\">vigilance</span></td></tr>\n        </tbody>\n      </table>\n      <p>Deux grands mécanismes peuvent concourir au <span class=\"kw-clinique\">coma</span> :</p>\n      <ul>\n        <li><strong>Souffrance cérébrale diffuse</strong> — cause <span class=\"kw-etio\">toxique</span>, <span class=\"kw-etio\">métabolique</span>, <span class=\"kw-etio\">traumatique</span>, <span class=\"kw-etio\">infectieuse</span> ou <span class=\"kw-etio\">épileptique</span></li>\n        <li><strong><span class=\"kw-clinique\">Lésion</span> cérébrale focale</strong> — <span class=\"kw-etio\">sous-tentorielle</span> ou <span class=\"kw-etio\">sus-tentorielle</span></li>\n      </ul>\n      <p>Sur le plan étiopathogénique, <span class=\"kw-clinique\">les</span> causes se répartissent en lésionnelles (atteinte structurelle) et fonctionnelles (atteinte diffuse réversible) :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Causes lésionnelles</strong></span></td>\n            <td>\n              <strong>Traumatiques :</strong> hématome extradural ; sous-dural ; intraparenchymateux<br>\n              <strong>Vasculaires :</strong> hémorragie méningée et ses complications (hématome parenchymateux, inondation ventriculaire, hydrocéphalie) ; <span class=\"kw-def\">AVC</span> (<span class=\"kw-clinique\">infarctus</span> du tronc basilaire, infarctus sylvien malin, hématome cérébral)<br>\n              <strong>Infectieuses :</strong> méningites sévères ; méningo-encéphalites (<span class=\"kw-def\">méningite</span> purulente, <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique)<br>\n              <strong><span class=\"kw-alerte\">HTIC</span> et engagement cérébral :</strong> effet de <span class=\"kw-clinique\">masse</span> d'une tumeur ; hydrocéphalie\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Causes fonctionnelles</strong></span></td>\n            <td>\n              <strong>Intoxication médicamenteuse ou récréative :</strong> <span class=\"kw-ttt\">benzodiazépines</span> ; <span class=\"kw-ttt\">opiacés</span> ; <span class=\"kw-etio\">alcool</span> ; <span class=\"kw-ttt\">antidépresseurs</span> ; <span class=\"kw-ttt\">neuroleptiques</span><br>\n              <strong>Troubles métaboliques :</strong> hypoglycémie ; hyponatrémie hypo-osmolaire ; état hyperglycémique hyperosmolaire ; encéphalopathie hypercapnique ; <span class=\"kw-alerte\">encéphalopathie hépatique</span><br>\n              <strong>État de <span class=\"kw-alerte\">choc</span></strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"336-3","rang":"A","rubrique":"Diagnostic positif","titre":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","contenu":"<p>Le <span class=\"kw-def\"><strong>coma</strong></span> est diagnostiqué cliniquement : yeux spontanément fermés, patient inconscient ne répondant pas de façon adaptée malgré une stimulation auditive puis nociceptive. Le <span class=\"kw-def\">stade</span> et la profondeur s'évaluent ensuite.</p>\n      <p><strong>Stades classiques du <span class=\"kw-clinique\">coma</span></strong></p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Dénomination</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 1</strong></td><td>état stuporeux (<span class=\"kw-clinique\">coma</span> vigil)</td><td>réponses possibles (phrases ± compréhensibles) aux stimulations répétées verbales et sensorielles ; <span class=\"kw-clinique\">mouvements de défense adaptés</span> contre la douleur</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 2</strong></td><td><span class=\"kw-clinique\">coma</span> léger</td><td><span class=\"kw-clinique\">réponse inadaptée</span> aux stimulations nociceptives ; pas de troubles neurovégétatifs</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 3</strong></td><td><span class=\"kw-clinique\">coma</span> carus / <span class=\"kw-clinique\">coma</span> profond</td><td><span class=\"kw-clinique\">mouvements de décérébration</span> aux stimulations nociceptives ou absence de réponse ; <span class=\"kw-alerte\">troubles neurovégétatifs</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 4</strong></td><td><span class=\"kw-clinique\">coma</span> dépassé</td><td>pas de réponse aux stimulations ; <span class=\"kw-alerte\">hypotonie</span> ; <span class=\"kw-alerte\">mydriase</span> ; <span class=\"kw-alerte\">abolition des fonctions végétatives</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Score de <span class=\"kw-def\">Glasgow</span></span> (GCS)</strong> — coté de <span class=\"kw-chiffre\">3</span> à <span class=\"kw-chiffre\">15</span>, somme de trois composantes.</p>\n      <table >\n        <thead><tr><th>Composante</th><th>Réponse</th><th><span class=\"kw-def\">Score</span></th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"4\"><span class=\"kw-def\"><strong>Ouverture des yeux (Y)</strong></span></td><td>spontanée</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>à la stimulation verbale</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>à la stimulation douloureuse</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>absente</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td rowspan=\"6\"><span class=\"kw-def\"><strong>Réponse motrice (M)</strong></span></td><td>sur commande</td><td><span class=\"kw-chiffre\">6</span></td></tr>\n          <tr><td>appropriée à la douleur</td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td>retrait, évitement</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>flexion anormale stéréotypée — <span class=\"kw-clinique\">décortication</span></td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>extension — <span class=\"kw-clinique\">décérébration</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>absente</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td rowspan=\"5\"><span class=\"kw-def\"><strong>Réponse verbale (V)</strong></span></td><td>orientée</td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td>confuse</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>incohérente</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>incompréhensible</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>absente</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/336/echelle-glasgow-illustration.png\" alt=\"Illustration clinique du score de Glasgow — ouverture des yeux, réponse motrice et réponse verbale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-def\">Score de <span class=\"kw-def\">Glasgow</span></span> : illustration des trois composantes (ouverture des yeux, réponse motrice, réponse verbale) et de leurs cotations. Source : fiche source EDN item 336 — <span class=\"kw-clinique\">Coma</span> non traumatique.</figcaption>\n      </figure>\n      <p><strong>Interprétation</strong> : conscience normale = <span class=\"kw-chiffre\">15</span> ; <span class=\"kw-alerte\">coma</span> = <span class=\"kw-chiffre\">≤ 7</span> ; <span class=\"kw-clinique\">coma</span> profond = <span class=\"kw-chiffre\">3</span>.</p>\n      <div class=\"callout callout-info\"><strong>Précisions de cotation.</strong> Le GCS retient la <strong>meilleure réponse</strong> de chaque item. Il ne prend pas en compte :\n        <ul>\n          <li>la <strong>réponse motrice</strong> d'un membre déficitaire (fracture ou cause neurologique)</li>\n          <li>la <strong>réponse verbale</strong> après <span class=\"kw-ttt\">intubation</span> orotrachéale</li>\n          <li>l'<strong>ouverture des yeux</strong> en cas de <span class=\"kw-clinique\">lésion</span> empêchant l'ouverture palpébrale</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source ne détaille pas le <span class=\"kw-alerte\">GCS pédiatrique</span> ni <span class=\"kw-clinique\">les</span> spécificités du <span class=\"kw-clinique\">coma</span> de l'enfant, alors que l'intitulé de l'objectif vise « l'adulte et l'enfant ». Kevin enrichira ce versant (échelle de <span class=\"kw-def\">Glasgow</span> adaptée à l'âge — réponse verbale du nourrisson notamment) depuis le Collège / Pilly.</div>","frequence":0},{"id":"336-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","contenu":"<p>L'examen neurologique du patient comateux repose sur quatre volets : la <strong>réactivité à la douleur</strong>, l'<strong>examen des yeux</strong>, la <strong>fonction ventilatoire</strong> et la recherche de <strong>signes de souffrance du tronc cérébral</strong>.</p>\n      <p><strong>1 · Réactivité à la stimulation nociceptive</strong></p>\n      <p>Manœuvres : friction du sternum, pression du lit unguéal, pincement du mamelon, pression du nerf sus-orbitaire, compression du nerf facial derrière le maxillaire inférieur.</p>\n      <table >\n        <thead><tr><th>Réponse observée</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Réaction d'éveil</span></td><td>ouverture des yeux, réaction d'orientation, réaction mimique (recherche un déficit facial central)</td></tr>\n          <tr><td>Absence de réponse d'un seul côté</td><td><span class=\"kw-clinique\">hémiplégie</span></td></tr>\n          <tr><td>Réponse appropriée</td><td>geste dirigé vers la stimulation : <span class=\"kw-clinique\">coma léger</span></td></tr>\n          <tr><td>Réponse inappropriée</td><td>geste sans finalité : souffrance des structures hémisphériques profondes ou de la partie haute du tronc cérébral</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Décortication</strong></span></td><td>membres supérieurs en <strong>flexion</strong> et adduction, membres inférieurs en <strong>extension</strong> → <span class=\"kw-alerte\">souffrance hémisphérique étendue</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Décérébration</strong></span></td><td>membres supérieurs en <strong>extension</strong>, adduction, rotation interne, membres inférieurs en <strong>extension</strong> → <span class=\"kw-alerte\">souffrance de la partie haute du tronc cérébral</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/336/posture-decortication-decerebration.webp\" alt=\"Postures de décortication et de décérébration chez un patient comateux\" loading=\"lazy\">\n        <figcaption>A — posture de décortication (membres supérieurs en flexion/adduction, membres inférieurs en extension) ; B — posture de décérébration (membres supérieurs en extension/adduction/rotation interne, membres inférieurs en extension). Source : fiche source EDN item 336 — <span class=\"kw-clinique\">Coma</span> non traumatique.</figcaption>\n      </figure>\n      <p><strong>2 · Examen des yeux</strong></p>\n      <table >\n        <thead><tr><th>Élément</th><th>Sémiologie et valeur localisatrice</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clignement et réflexe cornéen</strong></td><td>clignement à la <span class=\"kw-alerte\">menace</span> présent = persistance d'une activation corticale<br>abolition <strong>unilatérale</strong> du réflexe cornéen = signe de localisation (voie afférente du <span class=\"kw-def\">V</span> ou efférente du <span class=\"kw-def\">VII</span>)<br>abolition <strong>bilatérale</strong> = atteinte <span class=\"kw-alerte\">diencéphalo-mésencéphalique</span></td></tr>\n          <tr><td><strong>Mydriase aréactive</strong></td><td><strong>unilatérale :</strong> <span class=\"kw-alerte\">engagement temporal</span> (atteinte du III)<br><strong>bilatérale :</strong> mort cérébrale, souffrance mésencéphalique, encéphalopathie post-anoxique, <span class=\"kw-clinique\">hypothermie</span>, intoxication (anticholinergiques, imipraminiques, organophosphorés, barbituriques)</td></tr>\n          <tr><td><strong>Myosis aréactif</strong></td><td><span class=\"kw-clinique\">coma</span> <span class=\"kw-etio\">métabolique</span> ou <span class=\"kw-etio\">toxique</span> (morphiniques ++) ; myosis serré = <span class=\"kw-alerte\">souffrance de la partie basse du tronc</span> (pont ou bulbe) — mauvais <span class=\"kw-def\">pronostic</span></td></tr>\n          <tr><td><strong>Position des globes oculaires</strong></td><td>déviation conjuguée horizontale du côté de la <span class=\"kw-clinique\">lésion</span> (« regarde son hémicorps sain ») = <span class=\"kw-clinique\">lésion hémisphérique</span><br>déviation conjuguée horizontale vers l'<span class=\"kw-clinique\">hémiplégie</span> = <span class=\"kw-clinique\">lésion protubérantielle</span><br>strabisme horizontal = atteinte du III (dehors) ou du VI (dedans)<br>skew deviation (déviation oblique) = lésion du tronc cérébral</td></tr>\n          <tr><td><strong>Mouvements spontanés</strong></td><td>normaux : errance oculaire conjuguée horizontale<br><span class=\"kw-clinique\">bobbing oculaire</span> (descente rapide, pause, réascension lente) = <span class=\"kw-clinique\">lésion</span> protubérantielle</td></tr>\n          <tr><td><strong>Réflexes oculocéphaliques (« yeux de poupée »)</strong></td><td>mouvements passifs de la tête → déviation conjuguée des yeux dans le sens opposé<br>réponse présente des 2 côtés = intégrité du tronc cérébral ; absence = souffrance sévère du TC<br><span class=\"kw-alerte\">Contre-indiqué si suspicion de lésion du rachis cervical</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · Fonction ventilatoire</strong> — le type de respiration a une valeur localisatrice.</p>\n      <table >\n        <thead><tr><th>Type de respiration</th><th>Manifestation</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cheyne-Stokes</strong></td><td>alternance régulière de périodes d'apnée et d'hyperpnée</td><td>souffrance <span class=\"kw-clinique\">diencéphalique</span> ou <span class=\"kw-clinique\">mésencéphalique supérieure</span> ; perturbations métaboliques (aussi : SAS central, <span class=\"kw-def\">insuffisance cardiaque</span>)</td></tr>\n          <tr><td><strong>Hyperventilation neurogène centrale</strong></td><td>hyperpnée</td><td>souffrance <span class=\"kw-clinique\">méso-diencéphalique</span> ou <span class=\"kw-clinique\">mésencéphalique</span></td></tr>\n          <tr><td><strong>Respiration apneustique</strong></td><td>pauses en inspiration ou en expiration</td><td>souffrance de la <span class=\"kw-alerte\">partie basse du pont</span> (mauvais <span class=\"kw-def\">pronostic</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Dyspnée</span> de Kussmaul</strong></td><td>inspiration – pause – expiration – pause</td><td>souffrance de la partie basse du tronc ; <span class=\"kw-bio\">acidose métabolique</span></td></tr>\n          <tr><td><strong>Respiration ataxique</strong></td><td>respiration irrégulière et anarchique</td><td>souffrance <span class=\"kw-alerte\">bulbaire</span> précédant l'<span class=\"kw-alerte\">arrêt cardiaque</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>4 · Signes de souffrance du tronc cérébral et réflexes du TC</strong></p>\n      <p>Signes de souffrance : réaction de décortication à la nociception, perte des réflexes du TC (faire au minimum <span class=\"kw-clinique\">RPM</span> et <span class=\"kw-clinique\">réflexe cornéen</span>), mydriase aréactive. <span class=\"kw-clinique\">Les</span> <strong>signes neurovégétatifs</strong> par atteinte bulbaire sont des <span class=\"kw-alerte\">signes de gravité</span> : <span class=\"kw-alerte\">troubles du rythme cardiaque</span>, instabilité tensionnelle, anomalies respiratoires, troubles thermiques, marbrures, hypersudation, troubles digestifs.</p>\n      <table >\n        <thead><tr><th>Réflexe (de haut en bas)</th><th>Description (réponse normale)</th><th>Localisation</th><th><span class=\"kw-def\">Score</span> de Liège</th></tr></thead>\n        <tbody>\n          <tr><td>Clignement à la <span class=\"kw-alerte\">menace</span></td><td>activation du cortex occipital — n'est <strong>pas</strong> un réflexe du TC</td><td>cortico-sous-cortical</td><td>non coté</td></tr>\n          <tr><td>Fronto-orbiculaire</td><td>percussion de la glabelle → clignement des yeux</td><td>—</td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td>Oculo-céphalique vertical</td><td>flexion/extension de la tête → mouvement oculaire de sens inverse</td><td>mésencéphale</td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>Photomoteur</td><td>flash lumineux → iridoconstriction</td><td>mydriase : mésencéphale ; myosis : pont ou bulbe</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>Réflexe cornéen</td><td>stimulation cornéenne (V) → clignement (VII) et élévation du globe</td><td>—</td><td>non coté</td></tr>\n          <tr><td>Oculo-céphalique horizontal</td><td>rotation de la tête → mouvement oculaire de sens inverse</td><td>pont</td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td>Oculo-vestibulaire</td><td>injection d'eau glacée dans le CAE (VIII) → nystagmus</td><td>—</td><td>non coté</td></tr>\n          <tr><td>Réflexe de <span class=\"kw-clinique\">toux</span></td><td>aspiration trachéale chez un patient intubé</td><td>bulbe</td><td>non coté</td></tr>\n          <tr><td>Oculo-cardiaque</td><td>compression des globes oculaires → ralentissement de la FC</td><td>—</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Aucun réflexe</td><td>aucun réflexe du tronc cérébral présent</td><td>—</td><td><span class=\"kw-chiffre\">0</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-def\">score de Liège</span> complète le GCS dans <span class=\"kw-clinique\">les</span> traumatismes crâniens graves et explore les réflexes des <strong>3 étages du tronc cérébral</strong> dans le sens craniocaudal. Les <span class=\"kw-clinique\">réflexes oculocéphaliques verticaux</span> (Liège 4) s'abolissent <strong>avant</strong> les horizontaux (Liège 2). Le <span class=\"kw-clinique\">réflexe oculo-cardiaque</span> est le dernier à disparaître — son abolition doit faire évoquer une mort encéphalique.</div>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Un arrêt respiratoire peut survenir <span class=\"kw-alerte\">brutalement</span>, sans être précédé d'autres signes de souffrance du tronc cérébral, dans <span class=\"kw-clinique\">les</span> encéphalopathies toxiques — <span class=\"kw-ttt\">barbituriques</span> ++.</div>","frequence":4},{"id":"336-5","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","contenu":"<p>Le <span class=\"kw-clinique\">coma</span> est reconnu rapidement : patient aux yeux spontanément fermés, paraissant inconscient, ne répondant pas de façon adaptée malgré une stimulation auditive puis nociceptive. La démarche d'orientation suit ensuite des étapes hiérarchisées.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Éliminer un <span class=\"kw-alerte\">arrêt cardio-respiratoire</span></strong></td><td>séquence <span class=\"kw-def\">ABCD</span> : vérifier que le patient respire et que le pouls est présent</td></tr>\n          <tr><td><strong>2. Éliminer un contexte traumatique</strong></td><td>recherche d'un <span class=\"kw-alerte\">traumatisme crânien et/ou rachidien</span></td></tr>\n          <tr><td><strong>3. Rechercher une cause rapidement réversible</strong></td><td><span class=\"kw-bio\">glycémie capillaire</span> devant tout trouble neurologique ou psychiatrique (<span class=\"kw-clinique\">coma</span> hypoglycémique si <span class=\"kw-chiffre\">&lt; 3 mmol/L</span>)<br>intoxication par <span class=\"kw-ttt\">benzodiazépines</span> ou <span class=\"kw-ttt\">opioïdes</span> : test à l'antidote (<span class=\"kw-ttt\">flumazénil</span> / <span class=\"kw-ttt\">naloxone</span>) en IVD diagnostique</td></tr>\n          <tr><td><strong>4. Coter le <span class=\"kw-def\">score de <span class=\"kw-def\">Glasgow</span></span></strong></td><td>discuter une <span class=\"kw-clinique\">intubation orotrachéale</span></td></tr>\n          <tr><td><strong>5. Évaluation neurologique</strong></td><td>recherche notamment des <span class=\"kw-alerte\">signes de souffrance du tronc cérébral</span> (<span class=\"kw-alerte\">urgence</span> neurologique immédiate)</td></tr>\n          <tr><td><strong>6. <span class=\"kw-def\">Diagnostic étiologique</span></strong></td><td>orientation selon le <span class=\"kw-def\">terrain</span>, l'anamnèse et <span class=\"kw-clinique\">les</span> signes associés (<span class=\"kw-clinique\">fièvre</span>, signes méningés, signes de focalisation, contexte <span class=\"kw-etio\">toxique</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-bio\">glycémie capillaire</span> est systématique devant <strong>tout</strong> trouble neurologique ou psychiatrique : c'est un geste de réflexe qui pose immédiatement le diagnostic d'un <span class=\"kw-clinique\">coma</span> hypoglycémique, cause parfaitement réversible à <span class=\"kw-ci\">ne jamais</span> manquer.</div>","frequence":0},{"id":"336-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de mort cérébrale","contenu":"<p>La <span class=\"kw-def\"><strong>mort cérébrale</strong></span> (<span class=\"kw-clinique\">coma</span> dépassé, <span class=\"kw-def\">stade</span> 4) correspond à une abolition complète et définitive des fonctions de l'encéphale. <span class=\"kw-clinique\">Les</span> éléments cliniques évocateurs retrouvés dans la fiche source sont :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Aréactivité</span> totale aux stimulations</li>\n        <li><span class=\"kw-alerte\">Mydriase</span> bilatérale aréactive</li>\n        <li><span class=\"kw-alerte\">Hypothermie</span></li>\n        <li><span class=\"kw-alerte\">Apnée</span> (abolition de la ventilation spontanée)</li>\n        <li><span class=\"kw-alerte\">Collapsus circulatoire</span></li>\n        <li><span class=\"kw-bio\">Silence électrique</span> à l'<span class=\"kw-imagerie\">EEG</span></li>\n      </ul>\n      <p>Le <span class=\"kw-clinique\">réflexe oculo-cardiaque</span> est le <strong>dernier réflexe du tronc cérébral à disparaître</strong> : son abolition doit faire poser la question d'une mort encéphalique.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source du dossier <code>336-<span class=\"kw-clinique\">coma</span>-non-traumatique/</code> n'expose pas <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">critères diagnostiques réglementaires complets</span> de la mort encéphalique (<span class=\"kw-clinique\">coma</span> aréactif, abolition de tous les réflexes du tronc cérébral, absence de ventilation spontanée confirmée par épreuve d'hypercapnie, puis confirmation paraclinique par 2 <span class=\"kw-imagerie\">EEG</span> nuls ou <span class=\"kw-imagerie\">angioscanner</span>/<span class=\"kw-imagerie\">angiographie</span> cérébrale). Kevin enrichira ce paragraphe depuis le Collège.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 201 — Transplantation d'organe</em></p>","frequence":1},{"id":"336-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une hypoglycémie et la corriger","contenu":"<p>Le <span class=\"kw-def\"><strong>coma hypoglycémique</strong></span> est une cause de <span class=\"kw-clinique\">coma</span> <strong>parfaitement réversible</strong> à rechercher systématiquement. Le diagnostic repose sur la <span class=\"kw-bio\">glycémie capillaire</span> : <span class=\"kw-clinique\">coma</span> hypoglycémique si <span class=\"kw-chiffre\">&lt; 3 mmol/L</span> (valeur normale ≈ <span class=\"kw-chiffre\">3,9 mmol/L</span>).</p>\n      <p><strong>Signes cliniques évocateurs</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Sueurs abondantes</span></li>\n        <li><span class=\"kw-clinique\">Signe de Babinski bilatéral</span></li>\n        <li><span class=\"kw-clinique\">Hypothermie</span></li>\n        <li>Parfois <span class=\"kw-clinique\">crises convulsives</span></li>\n        <li>Parfois <span class=\"kw-clinique\">signes déficitaires localisés</span></li>\n      </ul>\n      <p><strong>Correction</strong></p>\n      <ul>\n        <li>Resucrage <strong>IV</strong> en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ttt\">sérum glucosé</span> (G30)</li>\n        <li><span class=\"kw-ttt\">Vitamine B1</span> systématiquement associée chez le patient <span class=\"kw-etio\">éthylique</span> ou <span class=\"kw-etio\">dénutri</span></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège vital.</strong> Chez l'éthylique ou le dénutri, l'apport de <span class=\"kw-ttt\">sérum glucosé</span> sans <span class=\"kw-ttt\">vitamine B1</span> peut <span class=\"kw-alerte\">précipiter une encéphalopathie de Gayet-Wernicke</span>. La vitamine B1 doit accompagner — voire précéder — le resucrage.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 240 — Hypoglycémie</em></p>","frequence":2},{"id":"336-8","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations d’urgence extrême d’un coma chez l’adulte et chez l’enfant","contenu":"<p>Certaines situations imposent une prise en charge <strong>immédiate</strong> car elles engagent le <span class=\"kw-alerte\">pronostic vital</span> ou neurologique à très court terme.</p>\n      <table >\n        <thead><tr><th>Situation d'<span class=\"kw-alerte\">urgence</span> extrême</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Coma hypoglycémique</strong></span></td><td>cause réversible : <span class=\"kw-bio\">glycémie capillaire</span> immédiate, resucrage IV sans délai</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Hypertension intracrânienne (HTIC)</strong></span></td><td><span class=\"kw-alerte\">menace</span> d'engagement — <span class=\"kw-alerte\">urgence</span> neurochirurgicale et de <span class=\"kw-alerte\">réanimation</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Engagement temporal</strong></span></td><td>secondaire à une <span class=\"kw-clinique\">lésion</span> <span class=\"kw-clinique\">sus-tentorielle</span> ; signe d'alerte = mydriase aréactive unilatérale (atteinte du III)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Engagement des amygdales cérébelleuses</strong></span></td><td>secondaire à une <span class=\"kw-clinique\">lésion</span> <span class=\"kw-clinique\">sous-tentorielle</span> ; risque de compression bulbaire et d'arrêt respiratoire</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> neurologique immédiate.</strong> Tout <span class=\"kw-alerte\">signe de souffrance du tronc cérébral</span> est une urgence. Un <span class=\"kw-clinique\">coma</span> avec <span class=\"kw-chiffre\">GCS &lt; 8</span> <span class=\"kw-alerte\">menace</span> <span class=\"kw-clinique\">les</span> voies aériennes et impose de les protéger (<span class=\"kw-ttt\">intubation</span> orotrachéale).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 331 — Arrêt cardio-circulatoire</em></p>","frequence":0},{"id":"336-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","contenu":"<p>Le bilan paraclinique d'un <span class=\"kw-clinique\">coma</span> associe imagerie cérébrale, biologie et examens orientés.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Imagerie cérébrale</strong></span></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">TDM</span> cérébrale</strong> non injectée puis injectée — <span class=\"kw-imagerie\">examen de choix</span>, en l'absence de cause évidente<br>\n              <strong><span class=\"kw-imagerie\">IRM</span> cérébrale</strong> en 1<sup>re</sup> intention si suspicion d'<span class=\"kw-def\">AVC</span>, de thrombophlébite cérébrale, de <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> ou de tumeur cérébrale\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Biologie</strong></span></td>\n            <td>\n              <strong>Sang :</strong> <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">gaz du sang</span> ; bilan d'hémostase ; <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">glycémie</span> ; <span class=\"kw-bio\">ammoniémie</span> ; fonction rénale ; fonction hépatique<br>\n              <strong>Toxiques</strong> (en l'absence d'étiologie évidente) : <span class=\"kw-etio\">alcool</span> ; <span class=\"kw-ttt\">benzodiazépines</span> ; <span class=\"kw-ttt\">antidépresseurs tricycliques</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examens orientés</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">Ponction lombaire</span> :</strong> si suspicion de <span class=\"kw-def\">méningite</span> ou d'<span class=\"kw-def\">encéphalite</span> — <span class=\"kw-alerte\">tout coma fébrile jusqu'à preuve du contraire</span><br>\n              <strong><span class=\"kw-bio\">ECG</span></strong> et <strong><span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span></strong><br>\n              <strong><span class=\"kw-imagerie\">EEG</span> :</strong> si suspicion de <span class=\"kw-clinique\">crise convulsive</span> ou de <span class=\"kw-clinique\">coma</span> métabolique (ex. <span class=\"kw-alerte\">encéphalopathie hépatique</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Quand peut-on se passer du <span class=\"kw-imagerie\">scanner</span> ?</strong> Seulement si l'ensemble du tableau est typique d'une cause <span class=\"kw-etio\">toxique</span> ou métabolique : anamnèse et examen physique concordants, <strong>pas de signe de localisation</strong> ni d'argument lésionnel, et profondeur du trouble cohérente avec la quantité de toxique ou l'ampleur du désordre métabolique.</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Un <span class=\"kw-alerte\">coma Glasgow 6 ne s'explique pas par une hyponatrémie modérée à 130 mmol/L</span> : la discordance entre profondeur du <span class=\"kw-clinique\">coma</span> et trouble métabolique impose de réaliser l'imagerie cérébrale.</div>","frequence":0},{"id":"336-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’IRM en urgence chez l’adulte et chez l’enfant","contenu":"<p>L'<span class=\"kw-imagerie\"><strong>IRM cérébrale</strong></span> est indiquée en <strong>1<sup>re</sup> intention</strong> devant un <span class=\"kw-clinique\">coma</span> lorsqu'on suspecte l'une des étiologies suivantes :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Accident vasculaire cérébral</span> (<span class=\"kw-def\">AVC</span>)</li>\n        <li><span class=\"kw-etio\">Thrombophlébite cérébrale</span></li>\n        <li><span class=\"kw-etio\">Méningo-encéphalite</span></li>\n        <li><span class=\"kw-etio\">Tumeur cérébrale</span></li>\n      </ul>\n      <p>Dans <span class=\"kw-clinique\">les</span> autres situations, la <span class=\"kw-imagerie\">TDM cérébrale</span> non injectée puis injectée reste l'examen de <span class=\"kw-chiffre\">première ligne</span> en <span class=\"kw-alerte\">urgence</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"336-11","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’une hémorragie intracrânienne","contenu":"<p>Sur la <span class=\"kw-imagerie\">TDM</span> cérébrale <strong>sans injection</strong>, un saignement récent apparaît en <span class=\"kw-radio\">hyperdensité spontanée</span> ; la topographie oriente le mécanisme :</p>\n      <ul>\n        <li><strong>Intraparenchymateuse</strong> — hématome <span class=\"kw-radio\">hyperdense</span> dans le parenchyme, entouré d'une <span class=\"kw-radio\">hypodensité péri-lésionnelle</span> (<span class=\"kw-clinique\">œdème</span>).</li>\n        <li><strong>Sous-arachnoïdienne</strong> — <span class=\"kw-radio\">hyperdensité des sillons, des vallées sylviennes et des citernes de la base</span>.</li>\n        <li><strong>Ventriculaire</strong> — rechercher une <span class=\"kw-radio\">inondation ventriculaire</span> (hyperdensité déclive intra-ventriculaire), facteur de <span class=\"kw-alerte\">gravité</span>.</li>\n      </ul>\n      <p>Toujours apprécier le <span class=\"kw-alerte\">retentissement</span> : effet de <span class=\"kw-clinique\">masse</span>, déviation de la ligne médiane, engagement.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/336/tdm-hemorragie-intracranienne.png\" alt=\"TDM cérébrale sans injection : hémorragie sous-arachnoïdienne des vallées sylviennes et hématome hémisphérique droit avec œdème péri-lésionnel\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> sans injection : <span class=\"kw-radio\">hyperdensités spontanées</span> des vallées sylviennes et de la citerne interpédonculaire (hémorragie sous-arachnoïdienne) ; hématome hémisphérique droit avec <span class=\"kw-radio\">œdème péri-lésionnel</span> et déviation de la ligne médiane. Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":0},{"id":"336-12","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’un effet de masse et d’un engagement cérébral","contenu":"<p>L'<strong>effet de <span class=\"kw-clinique\">masse</span></strong> traduit un processus expansif (hématome, tumeur, <span class=\"kw-clinique\">œdème</span>) ; signes <span class=\"kw-imagerie\">TDM</span> :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Déviation de la ligne médiane</span> ;</li>\n        <li><span class=\"kw-radio\">Effacement des sillons corticaux et des citernes de la base</span> ;</li>\n        <li><span class=\"kw-radio\">Collapsus du ventricule homolatéral</span> et dilatation du ventricule controlatéral.</li>\n      </ul>\n      <p>Complication = <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">engagements cérébraux</span> : <strong>sous-falcoriel</strong> (cingulaire), <strong>temporal</strong> (uncus → III, mydriase homolatérale), <strong>des amygdales cérébelleuses</strong> (→ bulbe, arrêt respiratoire).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/336/tdm-effet-masse-engagement.png\" alt=\"TDM cérébrale sans injection : hématome extra-dural droit biconvexe avec effet de masse, déviation de la ligne médiane et engagement sous-falcoriel\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> sans injection : hématome extra-dural droit <span class=\"kw-radio\">biconvexe</span> → <span class=\"kw-radio\">déviation de la ligne médiane</span>, effacement des sillons, collapsus du ventricule latéral droit et dilatation du gauche (<span class=\"kw-alerte\">engagement sous-falcoriel</span>). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":0},{"id":"336-13","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> causes de <span class=\"kw-clinique\">coma</span> non traumatique se regroupent en grandes familles étiologiques. Le <strong><span class=\"kw-clinique\">coma</span> <span class=\"kw-etio\">toxique</span></strong> est le plus fréquent.</p>\n      <p><strong>1 · <span class=\"kw-clinique\">Coma</span> <span class=\"kw-etio\">toxique</span></strong> (le plus fréquent)</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Éléments d'orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dogme</strong></td><td>évoqué devant tout <span class=\"kw-clinique\">coma</span> de cause inexpliquée (recherche de toxiques sang/urines : barbitémie, alcoolémie) et devant tout <span class=\"kw-clinique\">coma</span> dépassé (aréactivité, <span class=\"kw-alerte\">mydriase</span>, <span class=\"kw-clinique\">hypothermie</span>, apnée, collapsus, voire silence <span class=\"kw-imagerie\">EEG</span>)</td></tr>\n          <tr><td><strong>Overdose aux <span class=\"kw-ttt\">opioïdes</span></strong></td><td><span class=\"kw-clinique\">coma</span>, <span class=\"kw-clinique\">myosis serré</span>, <span class=\"kw-def\">dépression</span> respiratoire, traces de piqûres ; l'administration IV de <span class=\"kw-ttt\">naloxone</span> confirme le diagnostic</td></tr>\n          <tr><td><strong>Causes iatrogènes</strong></td><td><span class=\"kw-ttt\">barbituriques</span> : <span class=\"kw-clinique\">coma</span> calme et profond, hypotonique, avec <span class=\"kw-def\">dépression</span> respiratoire<br><span class=\"kw-ttt\">antidépresseurs tricycliques</span> (souvent associés aux BZD) : <span class=\"kw-clinique\">coma</span> avec <span class=\"kw-clinique\">convulsions</span>, mydriase, <span class=\"kw-alerte\">troubles du rythme</span></td></tr>\n          <tr><td><strong>Causes exogènes</strong></td><td>intoxication alcoolique aiguë<br>intoxication oxycarbonée : <span class=\"kw-clinique\">teinte cochenille</span>, <span class=\"kw-def\">syndrome pyramidal</span>, hypertonie, <span class=\"kw-clinique\">convulsions</span><br>organophosphorés (insecticides) : paralysie des muscles respiratoires, fasciculations, <span class=\"kw-clinique\">myosis serré</span> — antidote : <span class=\"kw-ttt\">atropine</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 · <span class=\"kw-clinique\">Coma</span> métabolique</strong> — évoqué devant un <span class=\"kw-clinique\">coma</span> d'installation rapidement progressive avec antécédents évocateurs.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Anoxie cérébrale</strong></span></td><td><span class=\"kw-alerte\">arrêt cardiaque</span>, <span class=\"kw-def\">choc cardiogénique</span>/<span class=\"kw-etio\">infectieux</span>/<span class=\"kw-etio\">hémorragique</span>, <span class=\"kw-alerte\">asphyxie</span>, <span class=\"kw-def\">embolie pulmonaire</span> ; troubles de vigilance + mouvements anormaux (<span class=\"kw-clinique\">astérixis</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Hypoglycémie</strong></span></td><td><span class=\"kw-clinique\">sueurs</span>, signe de Babinski bilatéral, <span class=\"kw-clinique\">hypothermie</span>, parfois <span class=\"kw-clinique\">convulsions</span> et signes déficitaires</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Troubles osmolaires</strong></span></td><td>encéphalopathie hypo-osmolaire (grandes <span class=\"kw-bio\">hyponatrémies</span> : troubles de vigilance + <span class=\"kw-clinique\">convulsions</span>) ou hyperosmolaire (<span class=\"kw-def\">diabète</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Encéphalopathie de Gayet-Wernicke</strong></span></td><td>carence en <span class=\"kw-ttt\">vitamine B1</span> : troubles de vigilance, <span class=\"kw-clinique\">paralysie oculomotrice</span>, troubles de l'équilibre, <span class=\"kw-def\">syndrome cérébelleux</span> ; aggravée par un sérum glucosé sans B1</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Encéphalopathie hépatique</strong></span></td><td><span class=\"kw-clinique\">coma</span> précédé d'une <span class=\"kw-clinique\">confusion avec astérixis</span> et d'une <span class=\"kw-clinique\">hypertonie oppositionnelle</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Insuffisance rénale</strong></span></td><td><span class=\"kw-clinique\">évolution</span> progressive ; manifestations motrices fréquentes (<span class=\"kw-clinique\">astérixis</span>, myoclonies, <span class=\"kw-clinique\">convulsions</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Causes endocriniennes</strong></span></td><td><span class=\"kw-def\">hypothyroïdie</span> sévère, insuffisance surrénale aiguë, hypercalcémie</td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · <span class=\"kw-clinique\">Coma</span> épileptique</strong></p>\n      <ul>\n        <li>Le <span class=\"kw-clinique\">coma</span> <span class=\"kw-clinique\">post-critique</span> n'excède pas <span class=\"kw-chiffre\">20 à 30 minutes</span> ; au-delà, envisager une complication (traumatique, vasculaire, <span class=\"kw-etio\">tumorale</span>, infectieuse, <span class=\"kw-etio\">toxique</span>, métabolique)</li>\n        <li>Devant un <span class=\"kw-clinique\">coma</span> sans notion de crise tonicoclonique : rechercher une <span class=\"kw-clinique\">perte d'urine</span>, une <span class=\"kw-clinique\">morsure de langue</span>, une respiration stertoreuse</li>\n        <li>En l'absence de phénomènes convulsifs, un <span class=\"kw-alerte\">état de mal épileptique non convulsif</span> justifie un <span class=\"kw-imagerie\">EEG</span> (activité paroxystique infraclinique)</li>\n      </ul>\n      <p><strong>4 · <span class=\"kw-clinique\">Coma</span> avec signes méningés</strong></p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Apyrétique</strong></td><td><span class=\"kw-etio\">hémorragie sous-arachnoïdienne</span> (<span class=\"kw-clinique\">coma</span> par <span class=\"kw-alerte\">HTIC</span>, vasospasme, hématome intraparenchymateux ou hydrocéphalie)</td></tr>\n          <tr><td><strong>Fébrile</strong></td><td><span class=\"kw-etio\">méningo-encéphalite bactérienne</span> (1<sup>re</sup> étiologie à évoquer) ; <span class=\"kw-def\">méningite</span> aseptique → foyer cérébral (<span class=\"kw-clinique\">abcès</span>) ou de voisinage (ORL, <span class=\"kw-clinique\">empyème</span>) ; <span class=\"kw-etio\">méningo-encéphalite herpétique</span> si aggravation rapide avec souffrance temporale ; <span class=\"kw-clinique\">accès pernicieux</span> palustre si séjour en zone d'endémie</td></tr>\n        </tbody>\n      </table>\n      <p><strong>5 · <span class=\"kw-clinique\">Coma</span> avec signes de focalisation</strong></p>\n      <table >\n        <thead><tr><th>Mode de début</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Début progressif</strong></td><td><span class=\"kw-etio\">processus expansif intracrânien</span> (tumeur, hématome sous-dural chronique)</td></tr>\n          <tr><td><strong>Début brutal</strong></td><td><span class=\"kw-etio\">hémorragie cérébrale</span> (<span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vomissements</span>, focalisation)<br><span class=\"kw-etio\">AVC ischémique</span> : <span class=\"kw-clinique\">œdème</span> cérébral (<span class=\"kw-clinique\">coma</span> retardé), <span class=\"kw-clinique\">infarctus</span> du tronc (<span class=\"kw-clinique\">coma</span> d'emblée si FRAA atteinte), infarctus du cervelet (<span class=\"kw-clinique\">coma</span> secondaire par compression du TC)<br>encéphalopathie hypertensive ; thrombophlébite cérébrale ; embolie gazeuse ou graisseuse</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Quatre situations d'<span class=\"kw-alerte\">urgence</span> extrême : <span class=\"kw-alerte\">coma hypoglycémique</span>, <span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-alerte\">engagement temporal</span> (<span class=\"kw-clinique\">lésion</span> sus-tentorielle), <span class=\"kw-alerte\">engagement des amygdales cérébelleuses</span> (lésion sous-tentorielle).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">AVC</span> · 341 — Hémorragie méningée · 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 337 — Intoxication aiguë · 105 — Epilepsie · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 279 — <span class=\"kw-def\">Cirrhose</span> · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique</em></p>","frequence":0},{"id":"336-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","contenu":"<p>La prise en charge initiale du patient comateux est <strong>symptomatique et étiologique en parallèle</strong>. <span class=\"kw-clinique\">Les</span> traitements de 1<sup>re</sup> ligne se déclinent en trois volets.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Ventilation</strong></span></td>\n            <td>\n              un <span class=\"kw-clinique\">coma</span> avec <span class=\"kw-chiffre\">GCS &lt; 8</span> impose de protéger <span class=\"kw-clinique\">les</span> voies aériennes<br>\n              mise en <span class=\"kw-clinique\">PLS</span><br>\n              <span class=\"kw-clinique\">intubation orotrachéale</span> généralement nécessaire si <span class=\"kw-chiffre\">GCS &lt; 8</span> (sauf cause rapidement réversible)<br>\n              le <span class=\"kw-clinique\">coma</span> hypercapnique du <span class=\"kw-etio\">BPCO</span> est la <strong>seule situation</strong> où la <span class=\"kw-ttt\">VNI</span> est possible malgré le trouble de vigilance\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Selon le contexte</strong></td>\n            <td>\n              <strong>Signes d'engagement :</strong> osmothérapie immédiate — <span class=\"kw-ttt\">mannitol</span> ou <span class=\"kw-ttt\">sérum salé hypertonique</span><br>\n              <strong>Suspicion d'intoxication BZD / <span class=\"kw-ttt\">opioïdes</span> :</strong> antidote (<span class=\"kw-ttt\">flumazénil</span> / <span class=\"kw-ttt\">naloxone</span>) en test diagnostique (IVD) ou thérapeutique (IVSE)<br>\n              <strong><span class=\"kw-def\">Syndrome méningé</span> fébrile :</strong> <span class=\"kw-ttt\">C3G à dose neuroméningée</span> après une paire d'<span class=\"kw-bio\">hémocultures</span><br>\n              <strong><span class=\"kw-clinique\">Coma</span> vasculaire :</strong> peut relever d'un traitement spécifique par <span class=\"kw-ttt\">thrombectomie</span> dans certains cas\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conditionnement</strong></td>\n            <td>\n              <strong>Circulation :</strong> VVC ; apport hydroélectrolytique ; vasopresseurs ; scope <span class=\"kw-bio\">ECG</span> ; monitoring de la PA<br>\n              <strong>Sondage urinaire :</strong> <span class=\"kw-def\">surveillance</span> de la diurèse<br>\n              <strong>Sonde nasogastrique :</strong> prévention de l'inhalation<br>\n              <strong>Glucose :</strong> systématique devant tout <span class=\"kw-clinique\">coma</span> inexpliqué, associé à la <span class=\"kw-ttt\">vitamine B1</span> chez le patient <span class=\"kw-etio\">éthylique</span> ou <span class=\"kw-etio\">dénutri</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Correction de l'hypoglycémie</strong> — devant une <span class=\"kw-bio\">glycémie capillaire</span> <span class=\"kw-chiffre\">&lt; 3 mmol/L</span> : resucrage IV par <span class=\"kw-ttt\">sérum glucosé</span>, avec <span class=\"kw-ttt\">vitamine B1</span> associée chez l'éthylique ou le dénutri.</p>\n      <div class=\"callout callout-danger\"><strong>Piège vital.</strong> Ne jamais perfuser de <span class=\"kw-ttt\">sérum glucosé</span> sans <span class=\"kw-ttt\">vitamine B1</span> chez l'éthylique ou le dénutri : risque de <span class=\"kw-alerte\">précipiter une encéphalopathie de Gayet-Wernicke</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 240 — Hypoglycémie</em></p>","frequence":0},{"id":"336-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures thérapeutiques associées des principales complications","contenu":"<p>Au-delà du traitement étiologique, le <span class=\"kw-clinique\">coma</span> expose à des complications dont la prévention et la correction font partie de la prise en charge.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mesure thérapeutique associée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Inhalation bronchique</span></td><td>protection des voies aériennes (PLS, <span class=\"kw-clinique\">intubation orotrachéale</span> si <span class=\"kw-chiffre\">GCS &lt; 8</span>) ; <span class=\"kw-clinique\">sonde nasogastrique</span> pour limiter le risque d'inhalation</td></tr>\n          <tr><td><span class=\"kw-alerte\">Signes d'engagement cérébral</span></td><td>osmothérapie immédiate : <span class=\"kw-ttt\">mannitol</span> ou <span class=\"kw-ttt\">sérum salé hypertonique</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Instabilité hémodynamique</span></td><td>VVC, apport hydroélectrolytique, <span class=\"kw-ttt\">vasopresseurs</span>, scope <span class=\"kw-bio\">ECG</span>, monitoring de la PA</td></tr>\n          <tr><td><span class=\"kw-alerte\">Troubles neurovégétatifs</span></td><td><span class=\"kw-def\">surveillance</span> rapprochée du rythme cardiaque, de la pression artérielle, de la température et de la fonction respiratoire (atteinte bulbaire)</td></tr>\n          <tr><td>Rétention et <span class=\"kw-def\">surveillance</span> de la diurèse</td><td><span class=\"kw-clinique\">sondage urinaire</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source détaille peu <span class=\"kw-clinique\">les</span> mesures thérapeutiques spécifiques des complications du <span class=\"kw-clinique\">coma</span> (prévention des complications de décubitus, escarres, thromboprophylaxie, nutrition, soins oculaires…). Kevin pourra enrichir ce paragraphe depuis le Collège de Médecine intensive – <span class=\"kw-alerte\">Réanimation</span>.</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale</span> ; <span class=\"kw-alerte\">défaillance</span> de la <span class=\"kw-def\">FRAA</span> (formation réticulée activatrice ascendante)<br><strong>Urgences extrêmes :</strong> <span class=\"kw-etio\">coma hypoglycémique</span> ; <span class=\"kw-alerte\">HTIC</span> ; <span class=\"kw-alerte\">engagement temporal</span> (<span class=\"kw-clinique\">lésion</span> sus-tentorielle) ; <span class=\"kw-alerte\">engagement des amygdales cérébelleuses</span> (lésion sous-tentorielle)<br><strong>1er geste :</strong> séquence <span class=\"kw-ttt\">ABCD</span> (absence d'<span class=\"kw-etio\">ACR</span> et de contexte traumatique) ; <span class=\"kw-ttt\">PLS</span> ; <span class=\"kw-bio\">glycémie capillaire</span> systématique</p>","hospit":"<p><strong>Hospit :</strong> tout <span class=\"kw-alerte\">coma</span> = <span class=\"kw-alerte\">hospitalisation en urgence</span> (jamais ambulatoire)<br><strong>Réa / IOT :</strong> <span class=\"kw-chiffre\">GSC &lt; 8</span> → protection des voies aériennes par <span class=\"kw-ttt\">intubation orotrachéale</span> (sauf cause rapidement réversible)<br><strong><span class=\"kw-ttt\">VNI</span> :</strong> uniquement si <span class=\"kw-etio\">coma hypercapnique</span> du <span class=\"kw-etio\">BPCO</span> malgré le trouble de vigilance</p>","redflags":"<ul><li><span class=\"kw-chiffre\">GSC &lt; 8</span> (<span class=\"kw-alerte\">coma</span> <span class=\"kw-chiffre\">≤ 7</span> ; <span class=\"kw-alerte\">coma</span> profond = 3) → indication d'<span class=\"kw-ttt\">intubation orotrachéale</span></li><li><span class=\"kw-alerte\">Signes de souffrance du tronc cérébral</span> = <span class=\"kw-alerte\">urgence</span> neurologique immédiate</li><li><span class=\"kw-clinique\">Décortication</span> (souffrance hémisphérique étendue) ou <span class=\"kw-clinique\">décérébration</span> (partie haute du TC) à la stimulation nociceptive</li><li><span class=\"kw-clinique\">Mydriase aréactive</span> : unilatérale (<span class=\"kw-etio\">engagement temporal</span>) ou bilatérale (souffrance <span class=\"kw-etio\">mésencéphalique</span> sévère, <span class=\"kw-etio\">mort cérébrale</span>)</li><li><span class=\"kw-clinique\">Myosis serré aréactif</span> : souffrance <span class=\"kw-etio\">pontique ou bulbaire</span> (mauvais <span class=\"kw-def\">pronostic</span>)</li><li>Perte des <span class=\"kw-clinique\">réflexes du tronc cérébral</span> (réflexe photomoteur, réflexe cornéen)</li><li><span class=\"kw-alerte\">Signes neurovégétatifs</span> (atteinte bulbaire) : troubles du rythme cardiaque, <span class=\"kw-etio\">HTA</span> ou <span class=\"kw-clinique\">hypotension</span>, anomalies respiratoires, hypo/<span class=\"kw-clinique\">hyperthermie</span>, marbrures, hypersudation</li><li>Rythmes respiratoires de mauvais <span class=\"kw-def\">pronostic</span> : respiration <span class=\"kw-clinique\">apneustique</span> (pont bas), <span class=\"kw-clinique\">ataxique</span> (bulbe, avant l'<span class=\"kw-alerte\">arrêt cardiaque</span>)</li><li><span class=\"kw-alerte\">Coma stade 3</span> (carus) : décérébration + troubles neurovégétatifs ; <span class=\"kw-alerte\">stade 4</span> (dépassé) : hypotonie, mydriase, abolition des fonctions végétatives</li><li>Risque d'<span class=\"kw-alerte\">arrêt respiratoire d'emblée</span> dans <span class=\"kw-clinique\">les</span> intoxications (barbituriques ++)</li><li><span class=\"kw-alerte\">HTIC</span> / engagement : mydriase aréactive + signes de focalisation</li></ul>","principes":"<p>PEC symptomatique immédiate et correction des causes rapidement réversibles, avant le traitement étiologique.</p><ul><li><strong>Ventilation :</strong> <span class=\"kw-chiffre\">GSC &lt; 8</span> → <span class=\"kw-ttt\">PLS</span> + <span class=\"kw-ttt\">intubation orotrachéale</span> (sauf cause réversible) ; <span class=\"kw-ttt\">VNI</span> seulement si <span class=\"kw-alerte\">coma</span> hypercapnique du BPCO</li><li><strong>Glucose :</strong> resucrage systématique devant tout <span class=\"kw-alerte\">coma</span> inexpliqué + <span class=\"kw-ttt\">vitamine B1</span> chez l'<span class=\"kw-etio\">éthylique</span> ou le <span class=\"kw-etio\">dénutri</span> (prévention Gayet-Wernicke)</li><li><strong>Antidotes :</strong> <span class=\"kw-ttt\">flumazénil</span> (BZD) / <span class=\"kw-ttt\">naloxone</span> (<span class=\"kw-ttt\">opioïdes</span>) en test diagnostique (IVD) puis thérapeutique (IVSE)</li><li><strong>Engagement cérébral :</strong> solution hypertonique immédiate (<span class=\"kw-ttt\">mannitol</span>, <span class=\"kw-ttt\">sérum salé hypertonique</span>)</li><li><strong><span class=\"kw-clinique\">Syndrome méningé</span> fébrile :</strong> <span class=\"kw-ttt\">C3G à dose neuroméningée</span> après 1 paire d'<span class=\"kw-bio\">hémocultures</span></li><li><strong><span class=\"kw-alerte\">Coma</span> vasculaire :</strong> <span class=\"kw-ttt\">thrombectomie</span> dans certains cas</li><li><strong>Conditionnement :</strong> <span class=\"kw-ttt\">VVC</span>, apport hydroélectrolytique, vasopresseurs, scope <span class=\"kw-imagerie\">ECG</span>, monitoring de la PA ; <span class=\"kw-ttt\">sondage urinaire</span> (diurèse) ; <span class=\"kw-ttt\">SNG</span> (éviter l'inhalation)</li></ul>","suivi":"<p><strong>Imagerie cérébrale</strong></p><ul><li><span class=\"kw-imagerie\">TDM cérébrale</span> non injectée puis injectée = examen de choix (en l'absence de cause évidente)</li><li><span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-chiffre\">1ère intention</span> : suspicion d'<span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">thrombophlébite cérébrale</span>, <span class=\"kw-etio\">méningo-encéphalite</span>, <span class=\"kw-etio\">tumeur</span></li><li><span class=\"kw-imagerie\">Scanner</span> évitable seulement si tableau typiquement <span class=\"kw-etio\">toxique</span>/métabolique concordant (clinique + profondeur cohérentes)</li></ul><p><strong>Biologie</strong></p><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">GDS</span>, bilan d'<span class=\"kw-bio\">hémostase</span></li><li><span class=\"kw-bio\">Ionogramme</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ammoniémie</span>, fonction rénale et hépatique</li><li><span class=\"kw-bio\">Toxiques</span> si pas d'étiologie évidente : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">BZD</span>, <span class=\"kw-etio\">antidépresseurs tricycliques</span></li></ul><p><strong>Autres examens</strong></p><ul><li><span class=\"kw-ttt\">Ponction lombaire</span> si suspicion de <span class=\"kw-alerte\">méningite</span>/<span class=\"kw-alerte\">encéphalite</span> (tout <span class=\"kw-alerte\">coma</span> fébrile jusqu'à preuve du contraire)</li><li><span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">radiographie thoracique</span></li><li><span class=\"kw-imagerie\">EEG</span> : suspicion de crise convulsive ou <span class=\"kw-alerte\">coma</span> métabolique (<span class=\"kw-alerte\">état de mal</span> non convulsif)</li></ul><p><strong><span class=\"kw-def\">Surveillance</span></strong></p><ul><li>Scope <span class=\"kw-bio\">ECG</span>, monitoring de la <span class=\"kw-clinique\">PA</span>, <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">diurèse</span></li><li>Évaluation neurologique répétée (<span class=\"kw-def\">GCS</span>)</li><li><span class=\"kw-etio\">Coma post-critique</span> : ne doit pas excéder <span class=\"kw-chiffre\">20-30 min</span> ; au-delà → rechercher une complication</li></ul>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/27.%20Coma%20non%20traumatique%20de%20l%27adulte.pdf","label":"CeMIR — 27. coma non traumatique de l'adulte"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Coma non traumatique — ABCD : respiration et pouls présents ; aréactif (stim. auditive puis nociceptive)","detail":"<h4>CAT — <span class=\"kw-alerte\">coma</span> non traumatique — Après vérification ABCD (absence d'<span class=\"kw-alerte\">ACR</span> et de contexte traumatique)</h4>","branches":[{"to":"q-reversible","label":"Étape initiale — glycémie capillaire","color":"blue"}]},{"id":"q-reversible","kind":"decision","label":"Cause rapidement réversible ? — Glycémie capillaire devant tout trouble neuro/psy","branches":[{"to":"t-hypo","label":"Hypoglycémie (&lt; 3 mmol/L)","color":"green"},{"to":"t-antidote","label":"Toxidrome opioïde / BZD","color":"green"},{"to":"q-gcs","label":"Non / coma persistant","color":"blue"}]},{"id":"t-hypo","kind":"terminal","label":"Coma hypoglycémique → resucrage","color":"green","detail":"<h4>Conduite</h4><ul><li>Resucrage IV par <span class=\"kw-ttt\">sérum glucosé</span></li><li>Ajouter <span class=\"kw-ttt\">vitamine B1</span> chez le patient <span class=\"kw-etio\">éthylique</span> ou <span class=\"kw-etio\">dénutri</span> (prévention Gayet-Wernicke)</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Glycémie capillaire</span> &lt; <span class=\"kw-chiffre\">3 mmol/L</span> (N 3,9)</li><li>Signes : <span class=\"kw-clinique\">sueurs</span> abondantes, signe de Babinski bilatéral, hypothermie</li></ul>"},{"id":"t-antidote","kind":"terminal","label":"Intoxication BZD / opioïde → antidote","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Naloxone</span> (<span class=\"kw-ttt\">opioïdes</span>) ou <span class=\"kw-ttt\">flumazénil</span> (BZD) en test diagnostique (IVD) puis thérapeutique (IVSE)</li></ul><h4>Confirmation</h4><ul><li>Overdose opioïde : <span class=\"kw-clinique\">myosis serré</span>, dépression respiratoire, traces de piqûres</li><li>Levée du <span class=\"kw-alerte\">coma</span> après administration de l'antidote</li></ul>"},{"id":"q-gcs","kind":"decision","label":"GSC &lt; 8 ? — Coma ≤ 7 ; coma profond = 3","branches":[{"to":"t-iot","label":"GSC &lt; 8","color":"red"},{"to":"q-etio","label":"GSC ≥ 8","color":"amber"}]},{"id":"t-iot","kind":"terminal","label":"Protection des voies aériennes — IOT","color":"red","detail":"<h4>Conduite</h4><ul><li>Mise en <span class=\"kw-ttt\">PLS</span> puis <span class=\"kw-ttt\">intubation orotrachéale</span> (sauf cause rapidement réversible)</li><li><span class=\"kw-ttt\">VNI</span> réservée au <span class=\"kw-etio\">coma hypercapnique du BPCO</span></li><li>Puis poursuite du bilan étiologique</li></ul>"},{"id":"q-etio","kind":"decision","label":"Orientation étiologique ? — Examen neurologique + contexte","branches":[{"to":"t-lesion","label":"Signes de focalisation","color":"red"},{"to":"t-meninge","label":"Syndrome méningé","color":"red"},{"to":"t-metabo","label":"Sans focalisation ni méningisme","color":"amber"}]},{"id":"t-lesion","kind":"terminal","label":"Signes de focalisation → cause lésionnelle","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">TDM cérébrale</span> non injectée puis injectée (examen de choix)</li><li><span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-chiffre\">1ère intention</span> si suspicion d'<span class=\"kw-alerte\">AVC</span>, thrombophlébite, <span class=\"kw-clinique\">méningo-encéphalite</span> ou tumeur</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Hémorragie cérébrale</span> (<span class=\"kw-alerte\">coma</span> brutal, <span class=\"kw-clinique\">céphalées</span>, vomissements)</li><li><span class=\"kw-etio\">AVC ischémique</span> (<span class=\"kw-clinique\">infarctus</span> du tronc cérébral ou du cervelet)</li><li><span class=\"kw-etio\">Processus expansif intracrânien</span></li><li><span class=\"kw-alerte\">Engagement</span> temporal ou des amygdales cérébelleuses</li></ul>"},{"id":"t-meninge","kind":"terminal","label":"Syndrome méningé → PL / imagerie","color":"red","detail":"<h4>Si fébrile</h4><ul><li>Tout <span class=\"kw-alerte\">coma fébrile</span> = <span class=\"kw-etio\">méningo-encéphalite</span> jusqu'à preuve du contraire</li><li>1 paire d'<span class=\"kw-bio\">hémocultures</span> puis <span class=\"kw-ttt\">C3G à dose neuroméningée</span> sans délai, puis <span class=\"kw-ttt\">ponction lombaire</span></li><li>Évoquer une <span class=\"kw-etio\">méningo-encéphalite herpétique</span> (souffrance temporale) ou un <span class=\"kw-etio\">accès pernicieux palustre</span> (zone d'endémie)</li></ul><h4>Si apyrétique</h4><ul><li>Évoquer une <span class=\"kw-etio\">hémorragie sous-arachnoïdienne</span> (<span class=\"kw-alerte\">HTIC</span>, vasospasme, hydrocéphalie) → <span class=\"kw-imagerie\">imagerie cérébrale</span></li></ul>"},{"id":"t-metabo","kind":"terminal","label":"Sans focalisation ni méningisme → cause toxique/métabolique","color":"amber","detail":"<h4>Conduite</h4><ul><li>Recherche de <span class=\"kw-bio\">toxiques</span> (sang/urines) : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">BZD</span>, <span class=\"kw-etio\">antidépresseurs tricycliques</span></li><li>Bilan métabolique : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ammoniémie</span>, fonction rénale et hépatique, <span class=\"kw-bio\">GDS</span></li><li><span class=\"kw-imagerie\">TDM cérébrale</span> sauf tableau typiquement <span class=\"kw-etio\">toxique</span>/métabolique concordant</li></ul><h4>Repères</h4><ul><li><span class=\"kw-alerte\">Coma</span> <span class=\"kw-etio\">toxique</span> = le plus fréquent</li><li><span class=\"kw-imagerie\">EEG</span> si suspicion de crise convulsive ou de <span class=\"kw-alerte\">coma</span> métabolique (<span class=\"kw-alerte\">état de mal</span> non convulsif)</li></ul>"}]},"cards":[{"i":"158f7b26cd12","n":336,"o":"336-1","u":"Définition","t":"Coma chez l’adulte et chez l’enfant","q":"Comment distinguer le coma des autres degrés d'altération de la conscience que sont l'obnubilation et l'état stuporeux ?","a":"<ul><li>L'<strong>obnubilation</strong> : le patient conserve une réaction aux <strong>ordres complexes</strong> (répond oralement, exécute des ordres, orientation temporo-spatiale normale), mais la réactivité est ralentie et moins précise.</li><li>L'<strong>état stuporeux</strong> : le patient conserve une réactivité à des <strong>stimuli extéroceptifs simples</strong> (appel du nom, stimulation auditive ou nociceptive), la réponse étant un geste ou une parole.</li><li>Le <strong>coma</strong> : suppression de la vigilance, le patient a les yeux spontanément fermés, est inconscient et <strong>ne répond pas</strong> de façon adaptée malgré une stimulation auditive puis nociceptive.</li></ul>"},{"i":"2510afee12a6","n":336,"o":"336-1","u":"Définition","t":"Coma chez l’adulte et chez l’enfant","q":"Comment les deux composantes de la conscience sont-elles schématiquement définies et régulées ?","a":"<p>La conscience se divise en deux composantes principales :</p><ul><li>L'<strong>éveil</strong> (ou vigilance) : régulé par des neurones du <strong>tronc cérébral</strong> (substance réticulée activatrice ascendante), de la partie postérieure du pont, du mésencéphale et du diencéphale. Il régit le niveau de vigilance (éveil, sommeil lent, sommeil paradoxal).</li><li>Le <strong>contenu conscient</strong> (conscience de soi et de l'environnement, awareness) : sous-tendu par un réseau de neurones à connexion longue distance, situés principalement dans les régions associatives <strong>préfrontales et pariétales</strong>.</li></ul>"},{"i":"48a172db8d5e","n":336,"o":"336-1","u":"Définition","t":"Coma chez l’adulte et chez l’enfant","q":"Quelle est la définition du coma et quelle est son évolution possible ?","a":"<p>Le coma est défini par une <strong>suppression de la vigilance</strong> (éveil). Le patient a les yeux spontanément fermés, paraît inconscient et ne répond pas de façon adaptée malgré une stimulation auditive puis nociceptive. Contrairement à d'autres états, le coma <strong>ne peut pas être réversible par un stimulus auditif ou douloureux</strong>, sauf en cas de coma dépassé. Il peut apparaître d'emblée ou faire suite à une obnubilation puis à une stupeur.</p>"},{"i":"61cfd4b1c438","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Quelles sont les principales étiologies de coma non traumatique associées à des signes méningés, en fonction de la présence ou non de fièvre ?","a":"<ul><li><strong>Coma apyrétique avec signes méningés</strong> : évoque une <strong>hémorragie sous-arachnoïdienne</strong> (coma par HTIC, vasospasme, hématome intraparenchymateux ou hydrocéphalie).</li><li><strong>Coma fébrile avec signes méningés</strong> : la <strong>méningo-encéphalite bactérienne</strong> est la première étiologie à évoquer. On peut aussi retrouver une méningite aseptique (foyer cérébral, ORL, empyème), une méningo-encéphalite herpétique (aggravation rapide, souffrance temporale) ou un accès pernicieux palustre (séjour en zone d'endémie).</li></ul>"},{"i":"ab2d591edaa4","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Comment différencier cliniquement une overdose aux opioïdes d'une intoxication aux antidépresseurs tricycliques, principales causes iatrogènes de coma toxique ?","a":"<ul><li>Une <strong>overdose aux opioïdes</strong> se manifeste par un coma, un <strong>myosis serré</strong>, une dépression respiratoire, et parfois des traces de piqûres. La <strong>naloxone IV</strong> est diagnostique et thérapeutique.</li><li>Une intoxication aux <strong>antidépresseurs tricycliques</strong> (souvent associés aux benzodiazépines) se caractérise par un coma avec <strong>convulsions</strong>, une <strong>mydriase</strong> et des troubles du rythme cardiaque.</li></ul>"},{"i":"be20cb5a4519","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Quelles sont les étiologies de coma avec signes de focalisation à début progressif et à début brutal ?","a":"<ul><li><strong>Début progressif</strong> : <strong>processus expansif intracrânien</strong> (tumeur, hématome sous-dural chronique).</li><li><strong>Début brutal</strong> : <strong>hémorragie cérébrale</strong> (céphalées, vomissements, focalisation), <strong>AVC ischémique</strong> (œdème cérébral avec coma retardé, infarctus du tronc cérébral avec coma d'emblée, infarctus du cervelet avec coma secondaire par compression), encéphalopathie hypertensive, thrombophlébite cérébrale, embolie gazeuse ou graisseuse.</li></ul>"},{"i":"cc77abafcfca","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Quelles sont les causes métaboliques de coma non traumatique et leurs particularités cliniques principales ?","a":"<ul><li><strong>Anoxie cérébrale</strong> : contexte d'arrêt cardiaque, choc, asphyxie, EP. Présence de troubles de vigilance et <strong>mouvements anormaux (astérixis)</strong>.</li><li><strong>Hypoglycémie</strong> : sueurs, <strong>signe de Babinski bilatéral</strong>, hypothermie, parfois convulsions ou signes déficitaires.</li><li><strong>Troubles osmolaires</strong> : encéphalopathie <strong>hypo-osmolaire</strong> (hyponatrémies s ou l'hyperosmolaire (diabète).</li><li><strong>Encéphalopathie de Gayet-Wernicke</strong> : carence en vitamine B1, avec troubles de vigilance, <strong>paralysie oculomotrice</strong>, troubles de l'équilibre et syndrome cérébelleux. Un sérum glucosé sans B1 l'aggrave.</li><li><strong>Encéphalopathie hépatique</strong> : précédée de confusion avec <strong>astérixis</strong> et hypertonie oppositionnelle.</li><li><strong>Insuffisance rénale</strong> : évolution progressive avec des manifestations motrices fréquentes (astérixis, myoclonies, convulsions).</li><li>Causes endocriniennes : hypothyroïdie sévère, insuffisance surrénale aiguë, hypercalcémie.</li></ul>"},{"i":"fcb3840b8cda","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Comment doit-on aborder la recherche étiologique d'un coma épileptique en l'absence de crise tonicoclonique observée ?","a":"<p>En l'absence de notion de crise tonicoclonique, il faut rechercher des signes indirects tels qu'une <strong>perte d'urine</strong>, une <strong>morsure de langue</strong> ou une <strong>respiration stertoreuse</strong>. Si des phénomènes convulsifs sont absents mais qu'un coma est présent, un <strong>état de mal épileptique non convulsif</strong> doit être évoqué et justifie un <strong>EEG</strong> pour rechercher une activité paroxystique infraclinique.</p>"},{"i":"fe2a71778312","n":336,"o":"336-13","u":"Étiologies","t":"Connaître les principales causes de coma non traumatique chez l’adulte et chez l’enfant","q":"Quelle est l'étiologie du coma non traumatique la plus fréquente, et quels sont les éléments qui orientent vers ce diagnostic ?","a":"<p>La cause la plus fréquente de coma non traumatique est le <strong>coma toxique</strong>. Il doit être évoqué devant :</p><ul><li>Tout coma de cause inexpliquée, nécessitant la recherche de toxiques (barbituriques, alcool) dans le sang et les urines.</li><li>Tout coma dépassé, caractérisé par l'aréactivité, une mydriase, une hypothermie, une apnée ou un collapsus, voire un silence EEG.</li></ul>"},{"i":"6c1f7fd24b85","n":336,"o":"336-14","u":"Prise en charge","t":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","q":"Quelle est la conduite à tenir systématique concernant le glucose devant tout coma inexpliqué ?","a":"<p>Devant tout coma inexpliqué, une administration de <strong>glucose</strong> est systématique, associée à la <strong>vitamine B1</strong> chez le patient <strong>éthylique ou dénutri</strong>.</p>"},{"i":"8059b180e68c","n":336,"o":"336-14","u":"Prise en charge","t":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","q":"Quelles sont les mesures de conditionnement initiales pour un coma non traumatique ?","a":"<p>Les mesures de conditionnement initiales d'un coma non traumatique comprennent :</p><ul><li>Pose d'une <strong>voie veineuse centrale (VVC)</strong>.</li><li>Apport <strong>hydroélectrolytique</strong>.</li><li>Administration de <strong>vasopresseurs</strong> si besoin.</li><li><strong>Monitorage ECG</strong> et de la <strong>PA</strong>.</li><li><strong>Sondage urinaire</strong> pour la surveillance de la diurèse.</li><li>Pose d'une <strong>sonde nasogastrique</strong> pour la prévention de l'inhalation.</li></ul>"},{"i":"af6dbf5e63c4","n":336,"o":"336-14","u":"Prise en charge","t":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","q":"Quelle est la prise en charge initiale générale d'un coma non traumatique ?","a":"<p>La prise en charge initiale d'un coma est <strong>symptomatique et étiologique</strong> en parallèle.</p>"},{"i":"f5b5352547b5","n":336,"o":"336-14","u":"Prise en charge","t":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","q":"Comment protège-t-on les voies aériennes d'un patient présentant un coma non traumatique ?","a":"<p>Pour protéger les voies aériennes d'un patient comateux :</p><ul><li>Mise en <strong>Position Latérale de Sécurité (PLS)</strong>.</li><li><strong>Intubation orotrachéale (IOT)</strong> est généralement nécessaire si le GCS est <strong>inférieur à 8</strong>, sauf si la cause est rapidement réversible.</li><li>La <strong>VNI</strong> est possible en cas de coma hypercapnique du BPCO, malgré le trouble de la vigilance.</li></ul>"},{"i":"ff147f978d8f","n":336,"o":"336-14","u":"Prise en charge","t":"Connaître la prise en charge symptomatique initiale et la correction d’une hypoglycémie","q":"Comment corriger une hypoglycémie (< 3 mmol/L) devant un coma et quelles sont les précautions à prendre ?","a":"<p>Devant une glycémie capillaire <strong>inférieure à 3 mmol/L</strong>, la correction se fait par <strong>resucrage IV par sérum glucosé</strong>. Il est impératif d'y associer de la <strong>vitamine B1</strong> chez le patient <strong>éthylique ou dénutri</strong> afin d'éviter le risque de précipiter une <strong>encéphalopathie de Gayet-Wernicke</strong>.</p>"},{"i":"45e575fd7dc3","n":336,"o":"336-3","u":"Diagnostic positif","t":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","q":"Comment interpréter le score de Glasgow (GCS) chez l'adulte pour évaluer la profondeur d'un coma ?","a":"<p>L'interprétation du score de Glasgow (GCS) pour l'évaluation du coma chez l'adulte est la suivante :</p><ul><li><strong>Conscience normale</strong> : GCS = <strong>15</strong>.</li><li><strong>Coma</strong> : GCS ≤ <strong>7</strong>.</li><li><strong>Coma profond</strong> : GCS = <strong>3</strong>.</li></ul>"},{"i":"aeaa22bed577","n":336,"o":"336-3","u":"Diagnostic positif","t":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","q":"Comment diagnostiquer cliniquement un coma non traumatique ?","a":"<p>Le diagnostic clinique du coma repose sur :</p><ul><li>Des <strong>yeux spontanément fermés</strong>.</li><li>Un patient <strong>inconscient</strong>.</li><li>L'absence de réponse adaptée, malgré une <strong>stimulation auditive puis nociceptive</strong>.</li></ul>"},{"i":"b16218cf6b75","n":336,"o":"336-3","u":"Diagnostic positif","t":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","q":"Quels sont les différents stades de profondeur du coma chez l'adulte, et leurs caractéristiques cliniques associées ?","a":"<p>La profondeur du coma est classée en plusieurs stades :</p><ul><li><strong>Stade 1 (état stuporeux / coma vigil)</strong> : réponses possibles (phrases plus ou moins compréhensibles) aux stimulations verbales et sensorielles répétées ; mouvements de défense adaptés contre la douleur.</li><li><strong>Stade 2 (coma léger)</strong> : réponse inadaptée aux stimulations nociceptives ; <strong>pas de troubles neurovégétatifs</strong>.</li><li><strong>Stade 3 (coma carus / coma profond)</strong> : mouvements de <strong>décérébration</strong> aux stimulations nociceptives ou <strong>absence de réponse</strong> ; présence de <strong>troubles neurovégétatifs</strong>.</li><li><strong>Stade 4 (coma dépassé)</strong> : <strong>pas de réponse</strong> aux stimulations ; hypotonie ; <strong>mydriase</strong> ; abolition des fonctions végétatives.</li></ul>"},{"i":"c5ff2a84261f","n":336,"o":"336-3","u":"Diagnostic positif","t":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","q":"Quelles sont les trois composantes évaluées par le score de Glasgow (GCS) chez l'adulte, et leur cotation maximale respective ?","a":"<p>Les trois composantes évaluées par le score de Glasgow (GCS) chez l'adulte et leur cotation maximale sont :</p><ul><li><strong>Ouverture des yeux (Y)</strong> : cotation maximale de <strong>4</strong> (spontanée).</li><li><strong>Réponse motrice (M)</strong> : cotation maximale de <strong>6</strong> (sur commande).</li><li><strong>Réponse verbale (V)</strong> : cotation maximale de <strong>5</strong> (orientée).</li></ul>"},{"i":"d47f12360fdd","n":336,"o":"336-3","u":"Diagnostic positif","t":"Diagnostiquer un coma, évaluer son stade et la profondeur du coma (Glasgow Coma Scale) chez l’adulte et chez l’enfant","q":"Quelles sont les précisions à prendre en compte lors de la cotation du score de Glasgow (GCS) chez l'adulte ?","a":"<p>Lors de la cotation du score de Glasgow (GCS) chez l'adulte, il est important de retenir <strong>la meilleure réponse de chaque item</strong>. Le GCS ne prend pas en compte :</p><ul><li>La réponse motrice d'un <strong>membre déficitaire</strong> (ex: fracture ou cause neurologique).</li><li>La réponse verbale <strong>après intubation orotrachéale</strong> (V non cotable, remplacé par N/C ou 1T).</li><li>L'ouverture des yeux en cas de <strong>lésion empêchant l'ouverture palpébrale</strong>.</li></ul>"},{"i":"0bef5ec0eca9","n":336,"o":"336-4","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","q":"Quels éléments de l'examen des yeux sont importants pour la localisation neurologique chez un patient comateux ?","a":"<p>Lors de l'examen des yeux chez un patient comateux, les éléments importants pour la localisation neurologique sont :</p><ul><li><strong>Clignement et réflexe cornéen</strong> :<ul><li>Clignement à la menace présent : persistance d'une activation corticale.</li><li>Abolition unilatérale du réflexe cornéen : signe de localisation (atteinte du <strong>V</strong> ou <strong>VII</strong>).</li><li>Abolition bilatérale : atteinte <strong>diencéphalo-mésencéphalique</strong>.</li></ul></li><li><strong>Mydriase aréactive</strong> :<ul><li>Unilatérale : <strong>engagement temporal</strong> (atteinte du <strong>III</strong>).</li><li>Bilatérale : <strong>mort cérébrale</strong>, souffrance mésencéphalique, encéphalopathie post-anoxique, hypothermie, intoxications (anticholinergiques, imipraminiques, organophosphorés, barbituriques).</li></ul></li><li><strong>Myosis aréactif</strong> :<ul><li>Coma métabolique ou <strong>toxique</strong> (morphiniques ++).</li><li>Myosis serré : souffrance de la partie basse du tronc (<strong>pont ou bulbe</strong>), de mauvais pronostic.</li></ul></li><li><strong>Position des globes oculaires</strong> :<ul><li>Déviation conjuguée horizontale du côté de la lésion (« regarde son hémicorps sain ») : <strong>lésion hémisphérique</strong>.</li><li>Déviation conjuguée horizontale vers l'hémiplégie : <strong>lésion protubérantielle</strong>.</li><li>Strabisme horizontal : atteinte du <strong>III</strong> (dehors) ou du <strong>VI</strong> (dedans).</li><li>Skew deviation (déviation oblique) : <strong>lésion du tronc cérébral</strong>.</li></ul></li><li><strong>Mouvements spontanés</strong> :<ul><li>Errance oculaire conjuguée horizontale : mouvements normaux.</li><li>Bobbing oculaire (descente rapide, réascension lente) : <strong>lésion protubérantielle</strong>.</li></ul></li><li><strong>Réflexes oculocéphaliques</strong> (« yeux de poupée ») : Une réponse présente des deux côtés indique une <strong>intégrité du tronc cérébral</strong>, son absence une souffrance sévère du tronc cérébral.</li></ul>"},{"i":"145501210a8b","n":336,"o":"336-4","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","q":"Quelle est la valeur localisatrice des différents types de respiration chez un patient comateux ?","a":"<p>La valeur localisatrice des différents types de respiration chez un patient comateux est la suivante :</p><ul><li><strong>Respiration de Cheyne-Stokes</strong> (alternance régulière d'apnée et d'hyperpnée) : souffrance <strong>diencéphalique ou mésencéphalique supérieure</strong>, ou perturbations métaboliques.</li><li><strong>Hyperventilation neurogène centrale</strong> (hyperpnée) : souffrance <strong>méso-diencéphalique ou mésencéphalique</strong>.</li><li><strong>Respiration apneustique</strong> (pauses en inspiration ou expiration) : souffrance de la <strong>partie basse du pont</strong> (mauvais pronostic).</li><li><strong>Dyspnée de Kussmaul</strong> (inspiration – pause – expiration – pause) : souffrance de la <strong>partie basse du tronc</strong> ou acidose métabolique.</li><li><strong>Respiration ataxique</strong> (irrégulière et anarchique) : souffrance <strong>bulbaire</strong>, précédant l'arrêt cardiaque.</li></ul>"},{"i":"6dec1929bff9","n":336,"o":"336-4","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","q":"Quels sont les quatre volets de l'examen neurologique d'un patient dans le coma ?","a":"<p>L'examen neurologique d'un patient dans le coma repose sur quatre volets essentiels :</p><ul><li>La <strong>réactivité à la stimulation nociceptive</strong>.</li><li>L'<strong>examen des yeux</strong>.</li><li>L'analyse de la <strong>fonction ventilatoire</strong>.</li><li>La recherche de <strong>signes de souffrance du tronc cérébral</strong>.</li></ul>"},{"i":"bf6933e8c07d","n":336,"o":"336-4","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","q":"Quels sont les signes cliniques de souffrance du tronc cérébral et les réflexes à évaluer pour les rechercher chez un patient comateux ?","a":"<p>Les signes cliniques de souffrance du tronc cérébral chez un patient comateux incluent :</p><ul><li>La réaction de <strong>décortication à la nociception</strong>.</li><li>La perte des <strong>réflexes du tronc cérébral</strong> (au minimum réflexe photomoteur et réflexe cornéen).</li><li>Une <strong>mydriase aréactive</strong>.</li></ul><p>Les signes neurovégétatifs par atteinte bulbaire sont des signes de gravité : troubles du rythme cardiaque, instabilité tensionnelle, anomalies respiratoires, troubles thermiques, marbrures, hypersudation, troubles digestifs.</p><p>Les réflexes du tronc cérébral à évaluer, de haut en bas, sont :</p><ul><li><strong>Fronto-orbiculaire</strong> (percussion de la glabelle).</li><li><strong>Oculo-céphalique vertical</strong> (flexion/extension de la tête, localisation mésencéphale).</li><li><strong>Photomoteur</strong> (flash lumineux, localisation mésencéphale, pont ou bulbe).</li><li><strong>Cornéen</strong> (stimulation cornéenne du V, réponse du VII).</li><li><strong>Oculo-céphalique horizontal</strong> (rotation de la tête, localisation pont).</li><li><strong>Oculo-vestibulaire</strong> (injection d'eau glacée dans le CAE).</li><li><strong>De toux</strong> (aspiration trachéale).</li><li><strong>Oculo-cardiaque</strong> (compression des globes oculaires, localisation bulbe).</li></ul><p>Le <strong>score de Liège</strong> permet de coter certains de ces réflexes et d'explorer les 3 étages du tronc cérébral.</p>"},{"i":"e545242024a0","n":336,"o":"336-4","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen neurologique d’un patient dans le coma","q":"Comment interpréter les réponses à la stimulation nociceptive chez un patient comateux ?","a":"<p>L'interprétation des réponses à la stimulation nociceptive chez un patient comateux est la suivante :</p><ul><li><strong>Réaction d'éveil</strong> (ouverture des yeux, orientation, réaction mimique) : évoque une vigilance résiduelle ou une recherche de déficit facial central.</li><li><strong>Absence de réponse d'un seul côté</strong> : suggère une <strong>hémiplégie</strong>.</li><li><strong>Réponse appropriée</strong> (geste dirigé vers la stimulation) : indique un <strong>coma léger</strong>.</li><li><strong>Réponse inappropriée</strong> (geste sans finalité) : témoigne d'une souffrance des structures hémisphériques profondes ou de la partie haute du tronc cérébral.</li><li><strong>Posture de décortication</strong> (membres supérieurs en flexion/adduction, membres inférieurs en extension) : signe une <strong>souffrance hémisphérique étendue</strong>.</li><li><strong>Posture de décérébration</strong> (membres supérieurs en extension/adduction/rotation interne, membres inférieurs en extension) : indique une <strong>souffrance de la partie haute du tronc cérébral</strong>.</li></ul>"},{"i":"253089a01ef5","n":336,"o":"336-5","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","q":"Quelle est la première étape de la démarche diagnostique devant un coma non traumatique, après élimination d'un arrêt cardio-respiratoire et d'un traumatisme ?","a":"<p>La première étape est de <strong>rechercher une cause rapidement réversible</strong> en réalisant systématiquement une <strong>glycémie capillaire</strong>.</p>"},{"i":"2c7e63171920","n":336,"o":"336-5","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","q":"Quel est le seuil glycémique définissant un coma hypoglycémique ?","a":"<p>Un coma est considéré comme hypoglycémique si la glycémie capillaire est <strong>inférieure à 3 mmol/L</strong>.</p>"},{"i":"72749add4429","n":336,"o":"336-5","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","q":"Comment définir cliniquement un coma non traumatique ?","a":"<p>Le coma non traumatique est caractérisé par un patient aux <strong>yeux spontanément fermés</strong>, paraissant inconscient, et <strong>ne répondant pas de façon adaptée</strong> malgré une stimulation auditive puis nociceptive.</p>"},{"i":"7efbeb6d65ce","n":336,"o":"336-5","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","q":"Dans quel contexte et avec quelles molécules peut-on réaliser des tests aux antidotes devant un coma non traumatique ?","a":"<p>En cas de suspicion d'intoxication, on peut réaliser un test diagnostique par <strong>injection IVD</strong> d'antidote :</p><ul><li><strong>Flumazénil</strong> en cas de suspicion d'intoxication par benzodiazépines.</li><li><strong>Naloxone</strong> en cas de suspicion d'intoxication par opioïdes.</li></ul>"},{"i":"b206c8b4932a","n":336,"o":"336-5","u":"Diagnostic positif","t":"Savoir rechercher les éléments d’orientation clinique et anamnestique devant un coma","q":"Quelle est l'importance de la glycémie capillaire devant tout trouble neurologique ou psychiatrique ?","a":"<p>La glycémie capillaire est <strong>systématique</strong> car elle permet de diagnostiquer rapidement un <strong>coma hypoglycémique</strong>, qui est une cause de coma parfaitement <strong>réversible</strong> et à ne jamais manquer.</p>"},{"i":"0623d6b266fe","n":336,"o":"336-7","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypoglycémie et la corriger","q":"Comment un diagnostic de coma hypoglycémique est-il confirmé ?","a":"<p>Le diagnostic de coma hypoglycémique est confirmé par la réalisation d'une <strong>glycémie capillaire</strong>. On parle de coma hypoglycémique si la glycémie est <strong>inférieure à 3 mmol/L</strong>.</p>"},{"i":"152db6aa3b07","n":336,"o":"336-7","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypoglycémie et la corriger","q":"Quel est le piège à éviter lors de la correction d'un coma hypoglycémique chez un patient éthylique ou dénutri ?","a":"<p>Chez un patient <strong>éthylique ou dénutri</strong>, l'apport de sérum glucosé <strong>sans vitamine B1</strong> peut précipiter une <strong>encéphalopathie de Gayet-Wernicke</strong>. La vitamine B1 doit donc accompagner, voire précéder, le resucrage chez ces patients.</p>"},{"i":"17d141563efe","n":336,"o":"336-7","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypoglycémie et la corriger","q":"Quels sont les signes cliniques évocateurs d'un coma hypoglycémique ?","a":"<p>Les signes cliniques évocateurs d'un coma hypoglycémique sont :</p><ul><li>Des <strong>sueurs abondantes</strong>.</li><li>Un <strong>signe de Babinski bilatéral</strong>.</li><li>Une <strong>hypothermie</strong>.</li><li>Parfois des <strong>crises convulsives</strong>.</li><li>Parfois des <strong>signes déficitaires localisés</strong>.</li></ul>"},{"i":"f4f935adfdae","n":336,"o":"336-7","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypoglycémie et la corriger","q":"Comment corriger en urgence un coma hypoglycémique ?","a":"<p>La correction en urgence d'un coma hypoglycémique se fait par un <strong>resucrage intraveineux</strong>, à l'aide de <strong>sérum glucosé (G30)</strong>.</p><p>Chez le patient <strong>éthylique ou dénutri</strong>, l'administration de <strong>vitamine B1</strong> est systématiquement associée, voire précède le resucrage.</p>"},{"i":"3ca285b860ab","n":336,"o":"336-8","u":"Identifier une urgence","t":"Identifier les situations d’urgence extrême d’un coma chez l’adulte et chez l’enfant","q":"Pourquoi un coma avec un score de Glasgow (GCS) inférieur à 8 est-il considéré comme une urgence extrême ?","a":"<p>Un coma avec un <strong>GCS inférieur à 8</strong> menace les <strong>voies aériennes</strong> et impose de les protéger par une <strong>intubation orotrachéale</strong>.</p>"},{"i":"73a0428bc9e4","n":336,"o":"336-8","u":"Identifier une urgence","t":"Identifier les situations d’urgence extrême d’un coma chez l’adulte et chez l’enfant","q":"Quel type de souffrance neurologique en cas de coma est considéré comme une urgence neurologique absolue ?","a":"<p>Tout signe de <strong>souffrance du tronc cérébral</strong> doit être considéré comme une urgence neurologique immédiate.</p>"},{"i":"ee1c5955357e","n":336,"o":"336-8","u":"Identifier une urgence","t":"Identifier les situations d’urgence extrême d’un coma chez l’adulte et chez l’enfant","q":"Quelles sont les situations d'engagement cérébral menaçant le pronostic vital ou neurologique lors d'un coma et leurs signes d'alerte spécifiques ?","a":"<ul><li>L'<strong>engagement temporal</strong>, secondaire à une lésion sus-tentorielle, dont le signe d'alerte est une <strong>mydriase aréactive unilatérale</strong> (atteinte du nerf oculomoteur III).</li><li>L'<strong>engagement des amygdales cérébelleuses</strong>, secondaire à une lésion sous-tentorielle, qui comporte un risque de <strong>compression bulbaire</strong> et d'<strong>arrêt respiratoire</strong>.</li></ul>"},{"i":"f18d9f7a8b74","n":336,"o":"336-8","u":"Identifier une urgence","t":"Identifier les situations d’urgence extrême d’un coma chez l’adulte et chez l’enfant","q":"Quelle est la cause de coma imposant une prise en charge immédiate en raison de sa réversibilité facile et son impact vital ?","a":"<p>Il s'agit du <strong>coma hypoglycémique</strong>. Il nécessite une <strong>glycémie capillaire immédiate</strong> et un <strong>resucrage IV sans délai</strong>.</p>"},{"i":"0318fec6b652","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Quelle est l'imagerie cérébrale de première intention à réaliser en urgence devant un coma non traumatique de l'adulte et de l'enfant ?","a":"<p>L'examen d'imagerie cérébrale de choix en urgence devant un coma non traumatique est la <strong>TDM cérébrale non injectée</strong>, puis injectée si nécessaire, en l'absence de cause évidente.</p>"},{"i":"62bbdf1105cd","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Dans quelles situations spécifiques l'EEG doit-il être réalisé devant un coma non traumatique ?","a":"<p>L'EEG doit être réalisé en cas de suspicion de <strong>crise convulsive</strong> ou de <strong>coma métabolique</strong> (par exemple, une encéphalopathie hépatique).</p>"},{"i":"bc1f1436f2dd","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Dans quels cas peut-on se passer d'une imagerie cérébrale de première intention devant un coma non traumatique ?","a":"<p>Il est possible de se passer d'imagerie cérébrale seulement si l'ensemble du tableau est typique d'une cause toxique ou métabolique. Cela implique :</p><ul><li>Une <strong>anamnèse</strong> et un <strong>examen physique concordants</strong>.</li><li>L'absence de <strong>signe de localisation</strong> ou d'argument lésionnel.</li><li>Une <strong>profondeur du trouble</strong> cohérente avec la quantité de toxique ou l'ampleur du désordre métabolique.</li></ul>"},{"i":"cca65d9b723c","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Quel est le piège classique à éviter concernant l'interprétation de la profondeur du coma et des troubles métaboliques ?","a":"<p>Un coma d'une profondeur importante (ex: <strong>Glasgow 6</strong>) ne s'explique pas par un trouble métabolique modéré (ex: hyponatrémie à 130 mmol/L). Une <strong>discordance</strong> entre la profondeur du coma et l'ampleur du trouble métabolique impose impérativement de réaliser l'<strong>imagerie cérébrale</strong> afin d'éliminer une lésion structurelle.</p>"},{"i":"d5a5f036363e","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Quels sont les examens biologiques sanguins systématiques à réaliser en urgence devant un coma non traumatique ?","a":"<p>Les examens biologiques sanguins systématiques sont :</p><ul><li><strong>NFS</strong> (Numération Formule Sanguine)</li><li><strong>Gaz du sang</strong></li><li><strong>Bilan d'hémostase</strong></li><li><strong>Ionogramme sanguin</strong></li><li><strong>Glycémie</strong></li><li><strong>Ammoniémie</strong></li><li>Bilan de la <strong>fonction rénale</strong></li><li>Bilan de la <strong>fonction hépatique</strong></li></ul>"},{"i":"ea193a0d01b9","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Quand faut-il réaliser une recherche de toxiques, et quels sont les toxiques à rechercher prioritairement devant un coma non traumatique ?","a":"<p>Une recherche de toxiques doit être réalisée en l'absence d'étiologie évidente. Les substances à rechercher prioritairement sont :</p><ul><li><strong>Alcool</strong></li><li><strong>Benzodiazépines</strong></li><li><strong>Antidépresseurs tricycliques</strong></li></ul>"},{"i":"f3f56f2b876f","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Dans quelles situations spécifiques l'IRM cérébrale est-elle l'examen d'imagerie de première intention devant un coma non traumatique ?","a":"<p>L'IRM cérébrale est l'examen d'imagerie de première intention en cas de suspicion :</p><ul><li>D'<strong>AVC</strong> (accident vasculaire cérébral)</li><li>De <strong>thrombophlébite cérébrale</strong></li><li>De <strong>méningo-encéphalite</strong></li><li>De <strong>tumeur cérébrale</strong></li></ul>"},{"i":"fe40a171cbc1","n":336,"o":"336-9","u":"Examens complémentaires","t":"Connaître les modalités de prescription des examens complémentaires à réaliser en urgence chez l’adulte et chez l’enfant","q":"Dans quelles situations spécifiques la ponction lombaire est-elle indiquée devant un coma non traumatique ?","a":"<p>La ponction lombaire est indiquée en cas de suspicion de <strong>méningite</strong> ou d'<strong>encéphalite</strong>. Tout coma <strong>fébrile</strong> impose une ponction lombaire jusqu'à preuve du contraire.</p>"}]};